export declare const SCENE_CSS = "\n.dr-scene {\n    position: relative;\n    overflow: hidden;\n    min-height: 120px;\n    background: var(--scene-bg, var(--bg));\n    border-radius: inherit;\n    isolation: isolate;\n}\n.dr-scene-host {\n    position: absolute;\n    inset: 0;\n}\n.dr-scene-canvas {\n    display: block;\n    touch-action: none;\n    outline: none;\n}\n.dr-scene-labels {\n    position: absolute;\n    inset: 0;\n    pointer-events: none;\n}\n.dr-scene-label {\n    font: 600 11px/1.2 var(--sans);\n    color: var(--fg);\n    padding: 2px 6px;\n    border-radius: var(--radius-sm);\n    white-space: nowrap;\n    background: color-mix(in srgb, var(--raised) 80%, transparent);\n    border-left: 3px solid var(--label-color, var(--primary));\n    transform: translateY(-14px);\n    transition: opacity 0.15s;\n}\n.dr-scene-label.dr-frame-label {\n    font-weight: 500;\n    font-size: 10px;\n    opacity: 0.8;\n    border-left-color: var(--label-color, var(--muted-fg));\n}\n.dr-scene-label.dr-highlight {\n    font-size: 12.5px;\n    font-weight: 700;\n    color: var(--primary-fg);\n    background: var(--primary);\n    border-left-color: var(--fg);\n    z-index: 2;\n}\n.dr-scene-label.dr-note {\n    white-space: pre;\n    text-align: center;\n    font-size: 12px;\n    color: var(--label-color, var(--warn));\n    border-left-color: var(--label-color, var(--warn));\n}\n.dr-scene-label.dr-covered {\n    opacity: 0;\n}\n.dr-scene-overlay {\n    position: absolute;\n    z-index: 2;\n    pointer-events: auto;\n}\n.dr-scene-controls {\n    position: absolute;\n    z-index: 2;\n    right: 10px;\n    bottom: calc(10px + var(--dim-inset-bottom, 0px));\n    display: flex;\n    flex-direction: column;\n    gap: 6px;\n}\n.dr-scene-controls--top-right { bottom: auto; top: 10px; }\n.dr-scene-controls--top-left { bottom: auto; top: 10px; right: auto; left: 10px; }\n.dr-scene-controls--bottom-left { right: auto; left: 10px; }\n.dr-scene-btn {\n    appearance: none;\n    display: inline-flex;\n    align-items: center;\n    justify-content: center;\n    width: 32px;\n    height: 32px;\n    padding: 0;\n    cursor: pointer;\n    color: var(--fg);\n    background: var(--glass, var(--surface));\n    backdrop-filter: var(--blur);\n    -webkit-backdrop-filter: var(--blur);\n    border: 1px solid var(--border);\n    border-radius: var(--radius);\n    transition: background 0.15s ease, border-color 0.15s ease;\n}\n.dr-scene-btn:hover {\n    background: var(--hover);\n    border-color: var(--border-strong);\n}\n.dr-scene-btn:focus-visible {\n    outline: none;\n    border-color: var(--ring);\n    box-shadow: var(--dr-focus);\n}\n.dr-scene-viewcube {\n    position: absolute;\n    z-index: 3;\n    top: 10px;\n    right: 10px;\n    touch-action: none;\n    filter: drop-shadow(0 1px 3px color-mix(in srgb, var(--bg) 60%, transparent));\n}\n.dr-scene-viewcube--top-left { right: auto; left: 10px; }\n.dr-scene-viewcube--bottom-right { top: auto; bottom: calc(10px + var(--dim-inset-bottom, 0px)); }\n.dr-scene-viewcube--bottom-left {\n    top: auto;\n    right: auto;\n    left: 10px;\n    bottom: calc(10px + var(--dim-inset-bottom, 0px));\n}\n.dr-scene-stats {\n    position: absolute;\n    z-index: 2;\n    left: 10px;\n    bottom: calc(10px + var(--dim-inset-bottom, 0px));\n    font: 11px/1.4 var(--mono);\n    color: var(--muted-fg);\n    padding: 3px 8px;\n    background: var(--glass, var(--surface));\n    border: 1px solid var(--border);\n    border-radius: var(--radius-pill);\n    pointer-events: none;\n}\n.dr-scene-stats--detailed {\n    border-radius: var(--radius);\n    display: grid;\n    gap: 1px;\n    left: auto;\n    right: 10px;\n    top: 10px;\n    bottom: auto;\n}\n/* point-style cards (StylePicker) */\n.dr-style-picker {\n    display: grid;\n    grid-template-columns: repeat(auto-fill, minmax(120px, 1fr));\n    gap: 6px;\n}\n.dr-style-card {\n    appearance: none;\n    display: grid;\n    grid-template-columns: 22px 1fr;\n    grid-template-rows: auto auto;\n    column-gap: 8px;\n    align-items: center;\n    text-align: left;\n    padding: 6px 8px;\n    cursor: pointer;\n    color: var(--fg);\n    font: inherit;\n    background: var(--surface);\n    border: 1px solid var(--border);\n    border-radius: var(--radius);\n}\n.dr-style-card:hover {\n    background: var(--hover);\n}\n.dr-style-card--on {\n    border-color: var(--primary);\n    box-shadow: inset 0 0 0 1px var(--primary);\n}\n.dr-style-card:focus-visible {\n    outline: none;\n    box-shadow: var(--dr-focus);\n}\n.dr-style-swatch {\n    grid-row: span 2;\n    width: 22px;\n    height: 22px;\n    border-radius: var(--radius-sm);\n    background: radial-gradient(circle at 35% 35%, var(--fg), var(--primary) 45%, transparent 70%);\n}\n.dr-style-swatch--voxel {\n    border-radius: 2px;\n    background: linear-gradient(135deg, var(--primary), color-mix(in srgb, var(--primary) 45%, var(--bg)));\n}\n.dr-style-swatch--splat {\n    background: radial-gradient(circle, var(--primary), transparent 70%);\n}\n.dr-style-swatch--square {\n    border-radius: 0;\n    background: var(--primary);\n}\n.dr-style-swatch--default {\n    background: repeating-linear-gradient(45deg, var(--muted-fg) 0 3px, transparent 3px 6px);\n}\n.dr-style-name {\n    font-size: 12.5px;\n    font-weight: 600;\n}\n.dr-style-about {\n    font-size: 11px;\n    color: var(--muted-fg);\n    line-height: 1.3;\n}\n.dr-range-inputs {\n    display: flex;\n    gap: 6px;\n}\n.dr-look-editor,\n.dr-layer-settings-grid {\n    display: grid;\n    gap: 8px;\n}\n/* LayersPanel */\n.dr-layers {\n    display: grid;\n    gap: 12px;\n}\n.dr-layer-group {\n    display: grid;\n    gap: 4px;\n}\n.dr-layer-group-title {\n    margin: 0;\n    font: 600 11px/1.3 var(--sans);\n    letter-spacing: 0.04em;\n    text-transform: var(--label-case, uppercase);\n    color: var(--muted-fg);\n}\n.dr-layer-row {\n    border: 1px solid transparent;\n    border-radius: var(--radius);\n    padding: 4px 6px;\n}\n.dr-layer-row--on {\n    background: color-mix(in srgb, var(--surface) 70%, transparent);\n    border-color: var(--border);\n}\n.dr-layer-line {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n}\n.dr-layer-name {\n    appearance: none;\n    flex: 1;\n    min-width: 0;\n    display: flex;\n    align-items: baseline;\n    gap: 6px;\n    padding: 2px 0;\n    font: inherit;\n    color: var(--fg);\n    text-align: left;\n    background: none;\n    border: 0;\n    cursor: pointer;\n}\n.dr-layer-name:disabled {\n    cursor: default;\n}\n.dr-layer-topic {\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n    font: 12.5px/1.3 var(--mono);\n}\n.dr-layer-type {\n    font-size: 11px;\n    color: var(--muted-fg);\n}\n.dr-layer-chevron {\n    margin-left: auto;\n    display: inline-flex;\n    color: var(--muted-fg);\n    transition: transform 0.15s;\n}\n.dr-layer-chevron--open {\n    transform: rotate(90deg);\n}\n.dr-layer-status {\n    margin: 2px 0 0 40px;\n    font: 11px/1.35 var(--mono);\n    color: var(--muted-fg);\n}\n.dr-layer-status--problem {\n    color: var(--warn);\n}\n.dr-layer-settings {\n    margin: 8px 0 4px;\n    padding: 8px;\n    border-top: 1px solid var(--border);\n}\n.dr-layer-other summary {\n    cursor: pointer;\n    font-size: 12px;\n    color: var(--muted-fg);\n}\n.dr-layer-other-topic {\n    display: flex;\n    justify-content: space-between;\n    gap: 8px;\n    font: 11.5px/1.5 var(--mono);\n}\n/* TfPanel */\n.dr-tf-panel {\n    display: grid;\n    gap: 8px;\n}\n.dr-hint {\n    margin: 0;\n    font-size: 12px;\n    color: var(--muted-fg);\n}\n.dr-tf-tree {\n    font: 12px/1.6 var(--mono);\n}\n.dr-tf-frame {\n    display: flex;\n    justify-content: space-between;\n    gap: 8px;\n    border-radius: var(--radius-sm);\n    cursor: default;\n}\n.dr-tf-frame:hover,\n.dr-tf-frame--highlighted {\n    background: var(--hover);\n}\n.dr-tf-frame--stale {\n    color: var(--warn);\n}\n.dr-tf-frame--flagged {\n    box-shadow: inset 2px 0 0 var(--warn);\n}\n.dr-tf-age {\n    color: var(--muted-fg);\n}\n.dr-tf-footnote {\n    appearance: none;\n    position: absolute;\n    z-index: 2;\n    left: 10px;\n    top: 10px;\n    display: inline-flex;\n    align-items: center;\n    gap: 6px;\n    max-width: calc(100% - 20px);\n    padding: 3px 8px;\n    font: 11.5px/1.4 var(--sans);\n    color: var(--warn);\n    cursor: pointer;\n    background: var(--glass, var(--surface));\n    border: 1px solid var(--warn-line, var(--border));\n    border-radius: var(--radius-pill);\n}\n.dr-tf-footnote span {\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n}\n.dr-gradient-picker {\n    display: grid;\n    grid-template-columns: repeat(auto-fill, minmax(38px, 1fr));\n    gap: 5px;\n    width: 100%;\n}\n.dr-gradient-picker__swatch {\n    appearance: none;\n    height: 14px;\n    padding: 0;\n    cursor: pointer;\n    border: 2px solid transparent;\n    border-radius: var(--radius-sm);\n}\n.dr-gradient-picker__swatch[aria-checked=\"true\"] {\n    border-color: var(--fg);\n}\n.dr-gradient-picker__swatch:focus-visible {\n    outline: none;\n    box-shadow: var(--dr-focus);\n}\n";
